// Custom domains schema (issue #24, spec §2 "Edge / domains", §10.1, §13).
//
// Conventions (spec §4): snake_case columns, camelCase TS fields, timestamptz
// in UTC, UUIDv7 ids generated by the app (never by the DB).
//
// SPEC-NOTE: `document_id` intentionally carries NO foreign key — the
// `documents` table belongs to T07's schema block and is not part of
// packages/db yet. Tenant scoping goes through workspace_id (FK to workspaces)
// and every repository read is workspace-scoped, so routing can never leak
// cross-tenant. Tighten with the FK when T07's documents DDL lands here.
//
// SPEC-NOTE: row-level security policies are owned by M1 (see identity.ts) —
// this file is table DDL only.

import { pgTable, text, timestamp, uuid } from "drizzle-orm/pg-core";
import { workspaces } from "./identity.ts";

/**
 * One attached custom hostname per row (spec §13: free 0 / pro 1 / business 5 —
 * the count is enforced by billing `can()`/`getEntitlements()`, not by the DB).
 * State machine: `pending → verified`. Only `verified` rows may appear in
 * `domain_routes` (the Host → documentId table the middleware reads).
 */
export const customDomains = pgTable("custom_domains", {
  id: uuid("id").primaryKey(),
  workspaceId: uuid("workspace_id")
    .notNull()
    .references(() => workspaces.id, { onDelete: "cascade" }),
  // Normalized (lowercase, no scheme/port/trailing dot); globally unique
  // because one host can only route to one document platform-wide.
  hostname: text("hostname").notNull().unique(),
  documentId: uuid("document_id").notNull(),
  // pending | verified — verification state visible in settings (issue #24)
  status: text("status").notNull().default("pending"),
  // Secret the customer publishes as TXT `_formforge-verify.<hostname>`
  verificationToken: text("verification_token").notNull(),
  lastCheckedAt: timestamp("last_checked_at", { withTimezone: true }),
  verifiedAt: timestamp("verified_at", { withTimezone: true }),
  lastError: text("last_error"),
  // manual | cloudflare — which provisioning path was used
  provisionMode: text("provision_mode").notNull().default("manual"),
  // Cloudflare for SaaS custom-hostname id (null in manual mode)
  customHostnameId: text("custom_hostname_id"),
  createdAt: timestamp("created_at", { withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

/**
 * The §8 "KV routing entry": Host → documentId, read on every public request
 * by the middleware (spec §10.1: "Middleware maps Host → documentId via
 * routing table"). Written ONLY by the domains service after a successful
 * verification; removed when the domain is removed or unrouted. This table is
 * the KV substitute until Cloudflare KV lands at the composition root.
 */
export const domainRoutes = pgTable("domain_routes", {
  hostname: text("hostname").primaryKey(),
  documentId: uuid("document_id").notNull(),
  workspaceId: uuid("workspace_id").notNull(),
  updatedAt: timestamp("updated_at", { withTimezone: true }).notNull().defaultNow(),
});

export const customDomainStatusValues = ["pending", "verified"] as const;
export type CustomDomainStatus = (typeof customDomainStatusValues)[number];
export const provisionModeValues = ["manual", "cloudflare"] as const;
export type ProvisionMode = (typeof provisionModeValues)[number];

export type CustomDomain = typeof customDomains.$inferSelect;
export type NewCustomDomain = typeof customDomains.$inferInsert;
export type DomainRoute = typeof domainRoutes.$inferSelect;
export type NewDomainRoute = typeof domainRoutes.$inferInsert;

export const domainTables = { customDomains, domainRoutes } as const;
